from datetime import date, datetime, timedelta, timezone
import unittest

import uniclubs_catalog
import uniclubs_database


NOW = datetime(2026, 11, 15, 17, tzinfo=timezone.utc)


class UniClubsCatalogTests(unittest.TestCase):
    """Convert independent catalog rows into normal source-aware planning objects."""

    def setUp(self):
        """Create only the independent public catalog in memory."""
        self.connection = uniclubs_database.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        uniclubs_database.init_db(self.connection)
        self.club_id = uniclubs_database.add_club(
            self.connection, 'club-a', 'Example Club',
            'https://uniclubs.ch/hsg/clubs/example-club')

    def add_event(self, identifier='event-a', **changes):
        """Insert one public source event with explicit field overrides."""
        record = {'external_id': identifier, 'club_id': self.club_id,
                  'title': 'Company networking', 'start_utc': '2026-11-16T11:00:00Z',
                  'end_utc': '2026-11-16T12:00:00Z', 'location': 'Online',
                  'event_type': 'career', 'publication_status': 'published',
                  'availability_state': 'open', 'requires_membership': False,
                  'source_url': 'https://uniclubs.ch/hsg/clubs/example-club/events/' + identifier}
        record.update(changes)
        return uniclubs_database.add_event(self.connection, record, now=NOW)

    def test_source_namespace_never_collides_with_integer_database_ids(self):
        """The same source UUID remains distinct from any positive legacy integer ID."""
        self.assertEqual(uniclubs_catalog.public_id('event-a'), 'uniclubs:event-a')
        self.assertEqual(uniclubs_catalog.external_id('uniclubs:event-a'), 'event-a')
        self.assertFalse(uniclubs_catalog.is_catalog_id(1))
        for invalid in (None, 1, '', 'uniclubs:', 'uniclubs: ', 'uniclubs: value'):
            with self.subTest(identifier=invalid):
                self.assertFalse(uniclubs_catalog.is_catalog_id(invalid))
                with self.assertRaises(ValueError):
                    uniclubs_catalog.external_id(invalid)

    def test_normal_adapter_keeps_source_ids_and_classifies_shared_features(self):
        """Create the existing domain shape without writing a legacy event record."""
        local_id = self.add_event()
        event = uniclubs_catalog.get_event(self.connection, 'uniclubs:event-a')
        self.assertNotEqual(local_id, event.event_id)
        self.assertEqual(event.series_id, 'uniclubs-series:event-a')
        self.assertEqual(event.club_id, 'uniclubs-club:club-a')
        self.assertEqual(event.direction_key, 'career')
        self.assertEqual(event.location_type, 'online')
        self.assertEqual(event.source_label(), 'Example Club')
        self.assertIsNone(event.price)
        self.assertTrue(event.can_confirm)

    def test_utc_times_are_converted_to_zurich_with_seasonal_offsets(self):
        """Use UTC source instants rather than interpreting them as floating local time."""
        self.add_event()
        self.add_event('summer', start_utc='2027-06-16T11:00:00Z',
                       end_utc='2027-06-16T12:00:00Z')
        winter = uniclubs_catalog.get_event(self.connection, 'uniclubs:event-a')
        summer = uniclubs_catalog.get_event(self.connection, 'uniclubs:summer')
        self.assertEqual(winter.start, datetime(2026, 11, 16, 12))
        self.assertEqual(summer.start, datetime(2027, 6, 16, 13))
        self.assertIsNone(winter.start.tzinfo)

    def test_queries_include_overlapping_events_and_sort_the_calendar(self):
        """Include an overnight event beginning before the visible window."""
        self.add_event('overnight', start_utc='2026-11-15T22:00:00Z',
                       end_utc='2026-11-16T01:00:00Z')
        self.add_event()
        rows = uniclubs_catalog.events_between(self.connection, date(2026, 11, 16),
                                               date(2026, 11, 17))
        self.assertEqual([event.event_id for event in rows],
                         ['uniclubs:overnight', 'uniclubs:event-a'])
        self.assertEqual(uniclubs_catalog.date_bounds(self.connection),
                         (date(2026, 11, 15), date(2026, 11, 16)))

    def test_registration_closed_is_distinct_from_cancellation(self):
        """Closed registration must not be described as an organizer cancellation."""
        self.add_event(availability_state='sales_closed')
        closed = uniclubs_catalog.get_event(self.connection, 'uniclubs:event-a')
        self.assertFalse(closed.source_cancelled)
        self.assertFalse(closed.can_confirm)
        self.assertIn('Registration closed', closed.display_tags())
        self.add_event('cancelled', publication_status='cancelled')
        cancelled = uniclubs_catalog.get_event(self.connection, 'uniclubs:cancelled')
        self.assertTrue(cancelled.source_cancelled)
        self.assertIn('Cancelled by organizer', cancelled.display_tags())

    def test_missing_source_remains_visible_but_cannot_be_newly_confirmed(self):
        """Keep retained metadata accessible with an explicit missing-source warning."""
        local_id = self.add_event()
        with self.connection:
            self.connection.execute('UPDATE events SET source_missing=1 WHERE id=?', (local_id,))
        rows = uniclubs_catalog.events_between(self.connection, date(2026, 11, 16),
                                               date(2026, 11, 17))
        self.assertEqual(len(rows), 1)
        self.assertTrue(rows[0].source_missing)
        self.assertFalse(rows[0].can_confirm)
        self.assertIn('Not in latest source snapshot', rows[0].display_tags())

    def test_unknown_end_is_only_estimated_for_display(self):
        """Do not invent a catalog duration or enable planning with an unknown source end."""
        self.add_event(end_utc=None)
        event = uniclubs_catalog.get_event(self.connection, 'uniclubs:event-a')
        self.assertTrue(event.end_is_estimated)
        self.assertFalse(event.can_confirm)
        self.assertEqual(event.end - event.start, timedelta(minutes=90))
        self.assertIsNone(self.connection.execute('SELECT end_utc FROM events').fetchone()[0])

    def test_long_program_is_not_a_continuous_confirmable_calendar_block(self):
        """A published program spanning weeks must remain an explicitly unchecked offer."""
        self.add_event(end_utc='2026-12-16T12:00:00Z')
        event = uniclubs_catalog.get_event(self.connection, 'uniclubs:event-a')
        self.assertTrue(event.is_multi_day())
        self.assertFalse(event.can_confirm)
        self.assertIn('Multi-day schedule — check original page', event.display_tags())

    def test_membership_and_limited_registration_remain_explicit(self):
        """Retain membership requirements while allowing an ordinary limited-availability plan."""
        self.add_event(requires_membership=True, availability_state='limited')
        event = uniclubs_catalog.get_event(self.connection, 'uniclubs:event-a')
        self.assertTrue(event.members_only)
        self.assertIn('Members only', event.display_tags())
        self.assertIn('Limited availability', event.display_tags())
        self.assertTrue(event.can_confirm)

    def test_invalid_row_does_not_make_the_whole_week_unavailable(self):
        """Skip one unrepresentable source interval and retain valid calendar events."""
        self.add_event()
        self.add_event('bad')
        with self.connection:
            self.connection.execute('''UPDATE events SET start_utc=?, end_utc=NULL
                WHERE external_id=?''', ('invalid', 'bad'))
        events = uniclubs_catalog.events_between(self.connection, date(2026, 11, 16),
                                                 date(2026, 11, 17))
        self.assertEqual([event.event_id for event in events], ['uniclubs:event-a'])
        with self.assertRaises(ValueError):
            uniclubs_catalog.get_event(self.connection, 'uniclubs:bad')

    def test_repeated_autumn_hour_does_not_invert_the_existing_naive_calendar_model(self):
        """Omit an actual positive UTC interval whose local wall-time end precedes its start."""
        self.add_event('autumn', start_utc='2027-10-31T00:45:00Z',
                       end_utc='2027-10-31T01:15:00Z')
        self.assertEqual(uniclubs_catalog.events_between(
            self.connection, date(2027, 10, 31), date(2027, 11, 1)), [])
        with self.assertRaises(ValueError):
            uniclubs_catalog.get_event(self.connection, 'uniclubs:autumn')

    def test_empty_catalog_and_invalid_query_boundaries_are_explicit(self):
        """Return empty bounds for no data and reject a reversed or aware range."""
        self.assertEqual(uniclubs_catalog.date_bounds(self.connection), (None, None))
        self.assertIsNone(uniclubs_catalog.get_event(self.connection, 'uniclubs:missing'))
        with self.assertRaises(ValueError):
            uniclubs_catalog.events_between(self.connection, date(2026, 11, 17),
                                            date(2026, 11, 16))
        with self.assertRaises(ValueError):
            uniclubs_catalog.events_between(self.connection, NOW, NOW + timedelta(days=1))


if __name__ == '__main__':
    unittest.main()
